  "track.storage.m.prefs.main.blocked": "bị chặn chờ đĩa",
  "track.storage.m.prefs.main.anr": "bị chặn lâu, nguy cơ ANR",
  "track.storage.m.prefs.main.free": "rảnh, vẽ được",
  "track.storage.m.prefs.saved.none": "chưa lưu",
  "track.storage.m.prefs.saved.mem": "chỉ trong bộ nhớ",
  "track.storage.m.prefs.saved.pending": "đang ghi xuống đĩa",
  "track.storage.m.prefs.saved.disk": "trên đĩa, đã xác nhận",
  "track.storage.m.prefs.saved.unknown": "không rõ: lỗi không được báo",
  "track.storage.cap.prefs": "Main thread ở trên, luồng IO ở dưới, file bên phải. Mũi tên cho biết ai đang ghi xuống đĩa; khối viền đỏ là main thread bị chặn hay lỗi bị nuốt.",
  "track.storage.m.prefs.s.commit.s1.title": "Bấm bật chủ đề tối: gọi commit() trên main",
  "track.storage.m.prefs.s.commit.s1.explain": "onClick chạy trên main thread và gọi commit(). commit đổi bản trong bộ nhớ rồi ghi xuống đĩa ngay trong lời gọi, và chỉ trả về khi ghi xong.",
  "track.storage.m.prefs.ev.commit.s1": "Bấm bật chủ đề tối: gọi commit() trên main",
  "track.storage.m.prefs.s.commit.s2.title": "Main thread đứng chờ ghi cả file",
  "track.storage.m.prefs.s.commit.s2.explain": "Trong mã AOSP, mỗi lần ghi viết lại toàn bộ file XML rồi sync. Suốt lúc đó main không vẽ khung hình nào và không nhận chạm nào.",
  "track.storage.m.prefs.ev.commit.s2": "Main thread đứng chờ ghi cả file",
  "track.storage.m.prefs.s.commit.s3.title": "Bộ nhớ chậm: main bị chặn lâu, nguy cơ ANR",
  "track.storage.m.prefs.s.commit.s3.explain": "Máy rẻ, bộ nhớ đang bận (đang cập nhật app khác). Ghi mất vài trăm mili giây hay hơn. Màn hình đứng; nếu một lần chạm không được phản hồi trong 5 giây, hệ thống báo ANR.",
  "track.storage.m.prefs.ev.commit.s3": "Bộ nhớ chậm: main bị chặn lâu, nguy cơ ANR",
  "track.storage.m.prefs.s.commit.s4.title": "commit() trả về true, màn hình mới vẽ lại",
  "track.storage.m.prefs.s.commit.s4.explain": "Ưu điểm duy nhất: biết chắc đã lưu (true) hay chưa (false). Cái giá là main thread đã đứng suốt thời gian ghi.",
  "track.storage.m.prefs.ev.commit.s4": "commit() trả về true, màn hình mới vẽ lại",
  "track.storage.m.prefs.s.apply.s1.title": "Bấm bật chủ đề tối: gọi apply()",
  "track.storage.m.prefs.s.apply.s1.explain": "apply đổi bản trong bộ nhớ ngay rồi trả về; việc ghi xuống đĩa được xếp hàng cho một luồng khác. Đọc lại khóa ngay sau đó thấy giá trị mới.",
  "track.storage.m.prefs.ev.apply.s1": "Bấm bật chủ đề tối: gọi apply()",
  "track.storage.m.prefs.s.apply.s2.title": "Luồng khác ghi cả file, main rảnh",
  "track.storage.m.prefs.s.apply.s2.explain": "Vẫn là ghi lại toàn bộ file và sync, nhưng ở luồng nền. Màn hình vẽ lại ngay.",
  "track.storage.m.prefs.ev.apply.s2": "Luồng khác ghi cả file, main rảnh",
  "track.storage.m.prefs.s.apply.s3.title": "Người dùng về màn hình chính: main chờ lần ghi dở",
  "track.storage.m.prefs.s.apply.s3.explain": "Activity chuyển sang onStop. Framework bảo đảm các lần apply() đang ghi phải xong trước khi Activity hay Service đổi trạng thái, nên main thread đứng chờ luồng ghi. Đĩa chậm thì đây chính là ANR.",
  "track.storage.m.prefs.ev.apply.s3": "Người dùng về màn hình chính: main chờ lần ghi dở",
  "track.storage.m.prefs.s.apply.s4.title": "Ghi lỗi: không ai được báo",
  "track.storage.m.prefs.s.apply.s4.explain": "Giả sử đĩa đầy và lần ghi thất bại. apply không có giá trị trả về và không gọi lại; bộ nhớ nói \"đã bật\", đĩa nói \"chưa\". Lần mở app sau, chủ đề tối biến mất.",
  "track.storage.m.prefs.ev.apply.s4": "Ghi lỗi: không ai được báo",
  "track.storage.m.prefs.s.datastore.s1.title": "Bấm bật chủ đề tối: edit trong viewModelScope",
  "track.storage.m.prefs.s.datastore.s1.explain": "onClick gọi ViewModel; ViewModel khởi chạy một coroutine gọi dataStore.edit. edit là hàm suspend nên main không chờ, nó chỉ tạm dừng coroutine.",
  "track.storage.m.prefs.ev.datastore.s1": "Bấm bật chủ đề tối: edit trong viewModelScope",
  "track.storage.m.prefs.s.datastore.s2.title": "DataStore ghi trên luồng IO, main rảnh",
  "track.storage.m.prefs.s.datastore.s2.explain": "Khối edit là một giao dịch đọc–sửa–ghi; DataStore ghi cả file (dữ liệu nhỏ, không cập nhật từng phần) trên dispatcher của nó, không trên main.",
  "track.storage.m.prefs.ev.datastore.s2": "DataStore ghi trên luồng IO, main rảnh",
  "track.storage.m.prefs.s.datastore.s3.title": "Người dùng về màn hình chính: main không chờ gì",
  "track.storage.m.prefs.s.datastore.s3.explain": "DataStore không đăng ký việc ghi vào hàng chờ của vòng đời Activity, nên onStop chạy ngay. Coroutine ghi vẫn chạy tiếp trên luồng của nó.",
  "track.storage.m.prefs.ev.datastore.s3": "Người dùng về màn hình chính: main không chờ gì",
  "track.storage.m.prefs.s.datastore.s4.title": "Flow phát giá trị mới, UI đổi màu",
  "track.storage.m.prefs.s.datastore.s4.explain": "data là một Flow; khi ghi xong nó phát Preferences mới và UI đang thu Flow đổi sang chủ đề tối. Nếu ghi lỗi, ngoại lệ ném ra từ edit ở đúng coroutine đã gọi, bắt được bằng try/catch.",
  "track.storage.m.prefs.ev.datastore.s4": "Flow phát giá trị mới, UI đổi màu",
  "track.storage.m.prefs.co.try": "Đi hết bốn bước của mỗi cách; đếm số ô gạch đỏ ở làn Main thread.",
  "track.storage.m.prefs.co.commit.s2": "Mã AOSP SharedPreferencesImpl: writeToFile ghi lại toàn bộ map bằng XmlUtils.writeMapXml rồi sync. [[src:aosp-sp-impl]]",
  "track.storage.m.prefs.co.commit.s3": "Trang ANRs: không phản hồi sự kiện nhập trong 5 giây thì bị báo ANR; I/O trên main thread là một nguyên nhân hay gặp. [[src:ax-anr]]",
  "track.storage.m.prefs.co.commit.s4": "Trang SharedPreferences.Editor: commit trả về true nếu giá trị mới đã ghi thành công xuống bộ nhớ bền. [[src:ax-sp-editor]]",
  "track.storage.m.prefs.co.apply.s2": "Trang SharedPreferences.Editor: apply đổi bản trong bộ nhớ ngay và bắt đầu ghi đĩa bất đồng bộ. [[src:ax-sp-editor]]",
  "track.storage.m.prefs.co.apply.s3": "Cùng trang đó cảnh báo: các lần apply() đang chờ có thể chặn main thread lúc chuyển vòng đời, một nguồn ANR hay gặp. [[src:ax-sp-editor]]",
  "track.storage.m.prefs.co.apply.s4": "Trang SharedPreferences.Editor: với apply, bạn không được báo nếu ghi thất bại. [[src:ax-sp-editor]]",
  "track.storage.m.prefs.co.datastore.s2": "Trang DataStore: updateData cập nhật theo giao dịch, một thao tác đọc–sửa–ghi nguyên tử; mọi mã trong khối là một giao dịch. [[src:ax-datastore]]",
  "track.storage.m.prefs.co.datastore.s3": "DataStore dùng coroutine và Flow để lưu bất đồng bộ, nhất quán và theo giao dịch. [[src:ax-datastore]]",
  "track.storage.m.prefs.co.datastore.s4": "Trang DataStore: đọc qua data, một Flow; trang khuyên đặt việc đọc ghi trong repository và ViewModel, không trong composable. [[src:ax-datastore]]",
  "track.storage.vz.tab.pf": "Làn luồng",
  "track.storage.vz.pf.cap": "Mỗi hàng là một làn, mỗi cột là một bước. Ô gạch đỏ ở làn Main thread là lúc màn hình đứng; ô gạch đỏ ở làn IO hay Đĩa là lỗi.",
  "track.storage.vz.pf.legend": "Ô gạch đỏ nối nhau ở làn Main thread là một đoạn main bị chặn: càng dài, màn hình càng đứng lâu.",
